import assert from "node:assert/strict";
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import test from "node:test";
import { ticketDeclaredFixtureDirectories } from "./workspace-skeleton.test.mjs";

const ticket = (...declarations) => [
  "# Fixture declaration",
  "",
  "## Exact ownership",
  ...declarations.map((declaration) => `- ${declaration}`),
  "",
  "## Preconditions",
  ""
].join("\n");

const writeFixture = (root, path) => {
  const absolutePath = resolve(root, path);
  mkdirSync(dirname(absolutePath), { recursive: true });
  writeFileSync(absolutePath, "fixture\n");
};

test("fixture admission census has canonical ordering independent of catalog and traversal order", () => {
  const root = mkdtempSync(join(tmpdir(), "aos-fixture-census-ordering-"));
  try {
    writeFixture(root, "fixtures/alpha/z-last.json");
    writeFixture(root, "fixtures/alpha/nested/a-first.json");
    writeFixture(root, "fixtures/bravo/allowed.json");
    writeFixture(root, "fixtures/bravo/refused.txt");
    writeFixture(root, "fixtures/zulu/child/one.json");

    const unreadable = "docs/tickets/D0/a-unreadable.md";
    const first = "docs/tickets/D0/b-multiple-declarations.md";
    const missingOwnership = "docs/tickets/D0/m-missing-ownership.md";
    const second = "docs/tickets/D0/z-multiple-declarations.md";
    const texts = new Map([
      [first, ticket("fixtures/bravo/*.json; fixtures/alpha/**")],
      [missingOwnership, "# Missing ownership section\n"],
      [second, ticket("fixtures/zulu/**; fixtures/alpha/**")]
    ]);
    const readTicket = (path) => texts.get(path);
    const expected = {
      catalogTicketPaths: [unreadable, first, missingOwnership, second],
      declarations: [
        { ticketPath: first, declaration: "fixtures/alpha/**" },
        { ticketPath: first, declaration: "fixtures/bravo/*.json" },
        { ticketPath: second, declaration: "fixtures/alpha/**" },
        { ticketPath: second, declaration: "fixtures/zulu/**" }
      ],
      directories: ["fixtures/alpha", "fixtures/bravo", "fixtures/zulu"],
      malformed: [
        { path: unreadable, reason: "unreadable" },
        { path: missingOwnership, reason: "ownership-section-missing" }
      ],
      admitted: [
        "fixtures/alpha/nested/a-first.json",
        "fixtures/alpha/z-last.json",
        "fixtures/bravo/allowed.json",
        "fixtures/zulu/child/one.json"
      ]
    };

    const census = (catalogTicketPaths) => ticketDeclaredFixtureDirectories({
      root,
      catalogTicketPaths,
      readTicket
    });
    const shuffled = census([missingOwnership, second, first, unreadable]);
    const reordered = census([unreadable, first, missingOwnership, second]);

    for (const [field, value] of Object.entries(expected)) {
      assert.deepEqual(shuffled[field], value, `${field} is not canonically ordered`);
      assert.deepEqual(reordered[field], value, `${field} changes when catalog order changes`);
    }
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});
